native_conditions.is_visible:
is_visible = {
		OR = {
			c:RUS ?= this
			AND = {
				exists = c:RUS
				is_subject_of = c:RUS
				country_is_subject_type_valid_for_caesaropapism = yes
			}
		}
		NOT = {
			has_law_or_variant = law_type:law_theocracy
		}
	}

is_visible = {
		c:RUS ?= this # For Russia and its subjects
	}

is_visible = {
		c:RUS ?= this
		country_has_monarchy_law = yes
		NAND = {
			has_technology_researched = central_archives # If has central archives, will not be available unless it's active
			NOT = {
				has_law = law_type:law_third_section
			}
		}
	}

native_conditions.can_enact:
can_enact = {
		OR = {
			is_country_type = colonial
			any_scope_state = {
				is_incorporated = no
			}
		}
	}

possible.possible:
possible = {
		country_has_monarchy_law = yes
		any_primary_culture = {
			has_discrimination_trait = heritage_east_slavic
		}
	}

russian_bloc_source:
c:RUS = {
		create_power_bloc = {
			name = ROSSIYSKAYA_IMPERIYA

			map_color = { 78 134 62 }

			founding_date = 1721.11.2 # Proclamation of the Russian Empire (Gregorian date).
			identity = identity_sovereign_empire
			principle = principle_vassalization_1
			member = c:PLC # Russian political influence, NOT subjecthood or annexation.
			member = c:CRI # Independent of Ottoman suzerainty since the 1774 treaty.

			# subjects are automatically part of the bloc
		}
		if = {
			limit = {
				has_dlc_feature = power_bloc_features
			}
			power_bloc = {
				add_principle = principle_defensive_cooperation_1
			}
		}
		# One-time native bloc-scope leverage, NOT a leave lock or forced rejoin.
		# Native cap is 1000 and influence subsequently drifts towards its target.
		power_bloc = {
			add_leverage = { target = c:PLC value = 650 }
			add_leverage = { target = c:CRI value = 550 }
		}
	}

caesaropapism_subject_helper.script:
country_is_subject_type_valid_for_caesaropapism = {
	religion = rel:orthodox
	OR = {
		is_subject_type = subject_type_colony
		is_subject_type = subject_type_dominion
		is_subject_type = subject_type_chartered_company
		is_subject_type = subject_type_crown_land
		is_subject_type = subject_type_personal_union
	}
}
